private int computeBinaryLog(int n) {
    // if the log of n is an integer, it means n is a power of 2
    if (Math.log(n) % 1 == 0) {
        return (int) (Math.log(n) + 1);
    }
    // otherwise, find the smallest power of 2 greater than or equal to n
    n = (int) Math.pow(2, Math.ceil(Math.log(n) / Math.log(2)));
    return (int) (Math.log(n) + 1);
}

