public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Convert the Set to a stream, then collect into a list of V objects
    List<V> vertices = tour.stream().map(edge -> graph.getEdgeSource(edge)).collect(Collectors.toList());

    // Define the flow of traffic between vertices
    int start = 0;
    int end = vertices.size() - 1;
    int[] flows = new int[end - start + 1];

    // Distribute the total flow and find the flow valves
    int totalFlow = tour.stream().mapToInt(vertex -> 1).sum();
    for (int i = 0; i < flows.length; i++) {
        flows[i] = totalFlow / (flows.length - i);
    }

    // Construct the graph path
    GraphPath<V, E> path = new GraphPath<>();
    for (int i = 0; i < tours.size(); i++) {
        E edge = tour.get(i);
        path.addVertex(graph.getEdgeSource(edge));
        path.addVertex(graph.getEdgeTarget(edge));
    }

    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    Map<E, List<V>> edgeToVertex = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        edgeToVertex.computeIfAbsent(edge, k -> new ArrayList<>()).add(source);
        edgeToVertex.computeIfAbsent(edge, k -> new ArrayList<>()).add(target);
    }

    GraphPath<V, E> path = new GraphPath<>();
    for (E edge : tour) {
        path.add(edgeToVertex.get(edge).get(0));
    }
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // HashMap to keep track of vertex indices
    HashMap<E, Integer> vertexMap = new HashMap<>();
    // List to represent the graph path
    List<E> path = new ArrayList<>();

    // Populate the vertexMap and path
    for (E edge : tour) {
        V src = edge.getSource();
        V dst = edge.getTarget();
        Integer srcIndex = vertexMap.get(src);
        Integer dstIndex = vertexMap.get(dst);

        // If the vertices are not in the vertexMap, add them to it
