private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    for (V v : vertices) {
        for (V w : vertices) {
            if (v != w) {
                boolean isAdjacent = graph.hasEdge(v, w);
                boolean isSame = v.equals(w);
                if (!isAdjacent && !isSame) {
                    return false;
                }
            }
        }
    }
    return true;
}

