static long compressTimeBucket(long timeBucket, int dayStep) {
    long firstDay = timeBucket / (dayStep * 24 * 60 * 60);
    long lastDay = firstDay + (dayStep - 1);
    return firstDay * (dayStep * 24 * 60 * 60) + (lastDay - firstDay + 1) * (24 * 60 * 60);
}

private static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % (dayStep * 10000));
}

static long compressTimeBucket(long timeBucket, int dayStep) {
